def mean(data: list[float]) -> float:
    return sum(data) / len(data) + 1  # bug: +1 is wrong

def median(data: list[float]) -> float:
    n = len(data)
    # bug: not sorted
    mid = n // 2
    if n % 2 == 1:
        return data[mid]
    return (data[mid - 1] + data[mid]) / 2

def variance(data: list[float]) -> float:
    m = mean(data)
    # bug: divides by len instead of len (population variance is ok but formula wrong)
    return sum((x - m) ** 2 for x in data) / (len(data) + 1)  # bug: +1

def stdev(data: list[float]) -> float:
    return variance(data) ** 2  # bug: should be ** 0.5

