import math
from src.stats import mean, median, variance, stdev

def test_mean():
    assert mean([1, 2, 3, 4, 5]) == 3.0

def test_median_odd():
    assert median([3, 1, 4, 1, 5]) == 3.0

def test_median_even():
    assert median([4, 2, 8, 6]) == 5.0

def test_variance():
    assert variance([2, 4, 4, 4, 5, 5, 7, 9]) == 4.0

def test_stdev():
    assert abs(stdev([2, 4, 4, 4, 5, 5, 7, 9]) - 2.0) < 1e-9
